# LangGraph state definition will be implemented here.

from typing import TypedDict


class SupportAgentState(TypedDict):

    # Customer's question
    question: str

    # Answer generated by RAG Service
    answer: str

    # Sources used to generate the answer
    sources: list[str]

    # Number of retries performed
    retry_count: int

    # Maximum allowed retries
    max_retries: int

    # Answer evaluation status
    answer_status: str

    # Whether human support is required
    needs_human: bool

    # Reason for escalating to human support
    escalation_reason: str
